<?php declare(strict_types=1);session_start();if(empty($_SESSION['user'])){header('Location: login.php');exit;}$u=$_SESSION['user'];if(($u['rol']??'')==='superadmin'){header('Location: panel.php');exit;}$config=require __DIR__.'/config.php';function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$q=$pdo->prepare('SELECT id,nombre,slug FROM tiendas WHERE id=?');$q->execute([(int)$u['tienda_id']]);$store=$q->fetch();$q=$pdo->prepare('SELECT id,nombre,precio,estado FROM productos WHERE tienda_id=? ORDER BY id DESC');$q->execute([(int)$u['tienda_id']]);$products=$q->fetchAll();}catch(Throwable $e){http_response_code(500);exit('No se pudo cargar el panel de tienda.');}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel de tienda</title><style>body{font-family:system-ui;background:#f6f3ee;margin:0}main{max-width:850px;margin:auto;padding:35px 20px}.card{background:#fff;padding:24px;border-radius:16px;margin:14px 0}a{color:#886c42}label{display:block;margin:8px 0 4px}input,textarea{box-sizing:border-box;width:100%;padding:9px;border:1px solid #ccc;border-radius:7px}button{margin-top:12px;background:#886c42;color:#fff;border:0;padding:10px 16px;border-radius:7px}.row{border-top:1px solid #eee;padding:10px 0}</style></head><body><main><p><a href="/">← Galería</a> · <a href="logout.php">Cerrar sesión</a></p><section class="card"><h1><?=h($store['nombre']??'Mi tienda')?></h1><p>Panel privado de tu tienda.</p><p><a href="tienda.php?slug=<?=urlencode($store['slug']??'')?>">Ver catálogo público →</a> · <a href="pedidos-admin.php">Ver pedidos →</a></p></section><section class="card"><h2>Agregar producto</h2><form method="post" action="producto-guardar.php"><input type="hidden" name="tienda_id" value="<?=$u['tienda_id']?>"><label>Nombre</label><input name="nombre" required><label>Descripción</label><textarea name="descripcion"></textarea><label>Precio</label><input type="number" name="precio" min="0" step="0.01" required><button>Publicar producto</button></form></section><section class="card"><h2>Mis productos</h2><?php foreach($products as $p):?><div class="row"><strong><?=h($p['nombre'])?></strong> · S/ <?=h((string)$p['precio'])?> · <?=h($p['estado'])?> · <a href="producto-editar.php?id=<?=$p['id']?>">Editar</a></div><?php endforeach;if(!$products):?><p>No hay productos.</p><?php endif;?></section></main></body></html>
